from kinloom import Kinloom

kl = Kinloom()

# --- stand-in for the game (plain Python, no engine) -----------------------------------------

WORLD = {
    "player": {"x": 50.0, "y": 50.0, "hp": 0.8},
    "enemies": [
        {"id": "e-%d" % i, "x": 50.0 + (i % 20), "y": 50.0 + (i // 20), "hp": 1.0, "armed": True}
        for i in range(200)
    ],
}

def dist(a, b):
    return ((a["x"] - b["x"]) ** 2 + (a["y"] - b["y"]) ** 2) ** 0.5

def allies_near(enemy, radius=15.0):
    return sum(1 for e in WORLD["enemies"] if e is not enemy and dist(e, enemy) < radius)

def senses_of(enemy):
    return {
        "hp": enemy["hp"],
        "dist": min(dist(enemy, WORLD["player"]), 40.0),
        "allies": min(allies_near(enemy), 10),
        "armed": enemy["armed"],
        "target": "fleeing" if enemy["hp"] < 0.3 else "alert",
    }

def apply(enemy, a):
    print(enemy["id"], a["action"], a["args"])   # the game would move/shoot the enemy here

# --- the crowd mind: declared once, decided per enemy every frame, no model call -------------

kl.mind(
    "grunt",
    "a skittish grunt: backs off when hurt, swarms and flanks when it has the numbers",
    senses={"hp": [0.0, 1.0], "dist": [0.0, 40.0], "allies": [0, 10], "armed": True,
            "target": ["idle", "alert", "fleeing"]},
    actions={"charge": {"speed": [1.0, 3.0]}, "shoot": {"burst": [1, 5]}, "flank": {}, "retreat": {}},
    rules={"retreat": ["hp low"],
           "shoot": ["armed", "dist below 20"],
           "flank": {"score": 0.8, "when": ["allies above 2", "target is alert"]},
           "charge": {"score": 0.5, "args": {"speed": "dist high"}}},
    learn=30,
)

# --- where the game loop would be: one think per enemy, every frame ---------------------------

for enemy in WORLD["enemies"]:
    a = kl.think("grunt", senses_of(enemy), who=enemy["id"])
    apply(enemy, a)
    kl.reward(enemy["id"], 0.1 if a["action"] == "flank" else -0.05)   # damage dealt minus taken
    if enemy["hp"] <= 0.0:
        kl.reward(enemy["id"], -1.0, done=True)                        # died: a loss

