kl = Kinloom()

# --- Stand-in for the game -------------------------------------------------
LANGUAGES = {"Ana": "Spanish", "Bram": "Dutch", "Chen": "Mandarin"}
INBOX = [                      # what the game already collected this tick
    {"from": "Ana", "text": "¿Dónde está la llave?"},
    {"from": "Bram", "text": "Ik sta bij de brug."},
    {"from": "Chen", "text": "我找到了一把剑。"},
]

def deliver(to, text):
    print(f"[to {to}] {text}")

# --- Translation -----------------------------------------------------------
def translate(speaker, text, listeners):
    """One text -> one line per listener, each in the language that listener reads."""
    langs = {name: LANGUAGES[name] for name in listeners}
    return kl.create(
        f"translate a chat message from {LANGUAGES[speaker]} into each listener's language",
        {name: "text" for name in langs},          # same shape back: one string per listener
        context={"from": LANGUAGES[speaker], "message": text, "into": langs},
    )

def chat_round(msgs):
    everyone = list(LANGUAGES)
    for msg in msgs:
        speaker = msg["from"]
        listeners = [p for p in everyone if p != speaker]
        for who, line in translate(speaker, msg["text"], listeners).items():
            deliver(who, line)

# --- The calls, where the game would make them -----------------------------
chat_round(INBOX)

