from kinloom import Kinloom

kl = Kinloom()

# --- Stand-in for the game (example values, no engine) ---
GUARDS = ["GARDE_EST", "GARDE_OUEST"]
PLAYER = "JOUEUR"
WITNESSES = ["GARDE_EST", "MARCHAND"]  # who was around when it happened

# Declare the guards once, in code: their voice and the lines they can say.
for name in GUARDS:
    kl.character(
        name,
        "un garde de la ville, méfiant, parle bref et factuel",
        lines={
            "vol_vu": ["{who} a volé, je l'ai vu de mes yeux."],
            "vol_rapporte": ["{who} a volé, {witness} l'a vu."],
        },
        events={
            "vol_vu": ["who"],
            "vol_rapporte": ["who", "witness"],
        },
    )

# --- Where the game would do this ---
def player_stole_bread():
    # The theft happened; tell Kinloom who saw it.
    kl.event("le joueur a volé du pain", by=PLAYER, seen_by=WITNESSES)

def guard_reacts(guard):
    # Did this guard see it themselves? Otherwise: did anyone they know see it?
    if kl.knows(guard, "le joueur a volé du pain"):
        return kl.say(guard, "vol_vu", {"who": PLAYER})
    for witness in WITNESSES:
        if kl.knows(witness, "le joueur a volé du pain"):
            return kl.say(guard, "vol_rapporte", {"who": PLAYER, "witness": witness})
    return None

# --- The calls, once, where the game would make them ---
player_stole_bread()
for guard in GUARDS:
    line = guard_reacts(guard)
    if line is not None:
        print(f"{guard}: {line}")

