    kl.character(
        g,
        guard_soul(g),
        lines={
            "heard_thief": [
                "So the player was seen stealing — {witness} swears it.",
                "Word travels: {witness} caught the player thieving.",
            ],
            "no_news": ["Nothing new on the streets tonight."],
        },
        events={
            "heard_thief": ["witness", "what"],
            "no_news": [],
        },
    )

# --- what the game would do when a theft happens ---
def player_steals(what, seen_by):
    kl.event(f"the player stole {what}", by="PLAYER", seen_by=seen_by, tag="theft", impact=0.8)

# the guards share what they know with each other
def guards_talk():
    for a in GUARDS:
        for b in GUARDS:
            if a != b:
                kl.meet(a, b)

